pub(super) const MIGRATION_V30: &str = r#"
ALTER TABLE provider_credential_verification_observations ADD COLUMN readiness_revision INTEGER CHECK(readiness_revision IS NULL OR readiness_revision > 0);
ALTER TABLE provider_credential_verification_observations ADD COLUMN release_tuple_digest BLOB CHECK(release_tuple_digest IS NULL OR length(release_tuple_digest) = 32);
CREATE TRIGGER provider_credential_verification_binding_insert BEFORE INSERT ON provider_credential_verification_observations WHEN NEW.readiness_revision IS NULL OR NEW.release_tuple_digest IS NULL OR length(NEW.release_tuple_digest) != 32 OR NEW.release_tuple_digest = zeroblob(32) OR NOT EXISTS(SELECT 1 FROM provider_credential_authority_heads AS h JOIN provider_credential_readiness_observations AS readiness ON readiness.provider_id = h.provider_id AND readiness.lifecycle_revision = h.lifecycle_revision AND readiness.readiness_revision = h.readiness_revision WHERE h.provider_id = NEW.provider_id AND h.lifecycle_revision = NEW.lifecycle_revision AND h.credential_fence = NEW.credential_fence AND h.readiness_revision = NEW.readiness_revision AND h.active_credential_version = NEW.active_credential_version AND h.active_ref_digest = NEW.active_ref_digest AND h.observed_at_high_water = NEW.started_at AND h.hard_fence_disposition IS NULL AND h.release_migration_state IN ('NONE', 'CLEARED') AND readiness.disposition = 'READY' AND readiness.active_binding_digest = NEW.active_ref_digest AND readiness.release_tuple_digest = NEW.release_tuple_digest) BEGIN SELECT RAISE(ABORT, 'credential verification lease requires current ready release binding'); END;
CREATE TRIGGER provider_credential_verification_binding_immutable BEFORE UPDATE ON provider_credential_verification_observations WHEN NEW.readiness_revision IS NOT OLD.readiness_revision OR NEW.release_tuple_digest IS NOT OLD.release_tuple_digest BEGIN SELECT RAISE(ABORT, 'credential verification readiness binding is immutable'); END;
CREATE TRIGGER provider_credential_verification_binding_complete BEFORE UPDATE ON provider_credential_verification_observations WHEN OLD.state = 'LEASED' AND NEW.state = 'COMPLETED' AND NOT EXISTS(SELECT 1 FROM provider_credential_authority_heads AS h JOIN provider_credential_readiness_observations AS readiness ON readiness.provider_id = h.provider_id AND readiness.lifecycle_revision = h.lifecycle_revision AND readiness.readiness_revision = h.readiness_revision WHERE h.provider_id = NEW.provider_id AND h.lifecycle_revision = NEW.lifecycle_revision AND h.credential_fence = NEW.credential_fence AND h.readiness_revision = NEW.readiness_revision AND h.active_credential_version = NEW.active_credential_version AND h.active_ref_digest = NEW.active_ref_digest AND h.observed_at_high_water = NEW.observed_at AND h.hard_fence_disposition IS NULL AND h.release_migration_state IN ('NONE', 'CLEARED') AND readiness.disposition = 'READY' AND readiness.active_binding_digest = NEW.active_ref_digest AND readiness.release_tuple_digest = NEW.release_tuple_digest) BEGIN SELECT RAISE(ABORT, 'credential verification completion requires current ready release binding'); END;
CREATE TRIGGER provider_credential_remote_verification_binding BEFORE INSERT ON provider_credential_verification_observations WHEN NEW.verification_kind = 'REMOTE' AND NOT EXISTS(SELECT 1 FROM provider_credential_verification_observations AS local WHERE local.provider_id = NEW.provider_id AND local.verification_kind = 'LOCAL' AND local.lifecycle_revision = NEW.lifecycle_revision AND local.credential_fence = NEW.credential_fence AND local.readiness_revision = NEW.readiness_revision AND local.release_tuple_digest = NEW.release_tuple_digest AND local.active_credential_version = NEW.active_credential_version AND local.active_ref_digest = NEW.active_ref_digest AND local.verifier_revision = NEW.verifier_revision AND local.state = 'COMPLETED' AND local.result = 'VERIFIED' AND local.observed_at <= NEW.started_at) BEGIN SELECT RAISE(ABORT, 'remote credential verification requires current local ready verification'); END;
"#;

pub(super) fn apply_v30_migration(conn: &Connection) -> SqliteResult<()> {
    let transaction = Transaction::new_unchecked(conn, TransactionBehavior::Exclusive)?;
    transaction.execute_batch(MIGRATION_V30)?;
    install_missing_v12_fence_triggers(&transaction)?;
    transaction.execute("INSERT INTO schema_version (version) VALUES (30)", [])?;
    transaction.commit()
}
